warp:
shader_body
{
vec2 _uv = uv;


   _uv = _uv - vec2(0.0,1.0)*texsize.zw*0.0;

    vec2 d2 = texsize.zw*12.0;
    float dx = ( 2.0*((texture(sampler_blur2, _uv + vec2(1.0,0.0)*d2).xyz * scale2) + bias2) - 2.0*((texture(sampler_blur2, _uv-vec2(1.0,0.0)*d2).xyz * scale2) + bias2) ).y*0.5;
    float dy = ( 2.0*((texture(sampler_blur2, _uv + vec2(0.0,1.0)*d2).xyz * scale2) + bias2) - 2.0*((texture(sampler_blur2, _uv-vec2(0.0,1.0)*d2).xyz * scale2) + bias2) ).y*0.5;
    vec2 my_uv = _uv - vec2(dx,dy)*0.08;



    ret.y = texture( sampler_fc_main, my_uv - floor(my_uv)).y;
    ret.y += (2.0*ret.y - 2.0*((texture(sampler_blur1, my_uv - floor(my_uv)).xyz * scale1) + bias1).y)*.05125 + 0.02;

    float d = 0.01;
    dx = ( 2.0*((texture(sampler_blur2, _uv + vec2(d,0.0)).xyz * scale2) + bias2) - 2.0*((texture(sampler_blur2, _uv-vec2(d,0.0)).xyz * scale2) + bias2) ).x*1280.0*texsize.z*0.5;
    dy = ( 2.0*((texture(sampler_blur2, _uv + vec2(0.0,d)).xyz * scale2) + bias2) - 2.0*((texture(sampler_blur2, _uv-vec2(0.0,d)).xyz * scale2) + bias2) ).x*1024.0*texsize.w*0.5;
    my_uv = _uv + vec2(dx,dy)*0.01;

    ret.x = texture( sampler_fw_main, my_uv).x;


    ret.x += (2.0*ret.x - 2.0*((texture(sampler_blur3, _uv).xyz * scale3) + bias3).x - 0.04)*.1;
    my_uv = _uv - vec2(dy,-dx)*0.04;

    ret.z = texture( sampler_fw_main, my_uv).z;

    ret.z += (2.0*ret.z - 2.0*((texture(sampler_blur1, _uv).xyz * scale1) + bias1).z)*0.5;
    ret.z *= 0.9*(ret.x + ret.y*0.64 - 1.0);
    ret.z += 0.02;


//ret = 0.0;


}

